**Thinking:** The workspace data lake is empty, but the ASD tools default to `/biolab_data/data_lake/`. Let me inspect that location for the ASD release files (AS, AP, DR) and any modulator dictionary that maps ASD modulator IDs to chemical names.

<execute>
import os, glob
roots = ["/biolab_data/data_lake", "/biolab_data", "/data"]
for r in roots:
    print("="*70)
    print(r, "exists:", os.path.exists(r))
    if os.path.exists(r):
        try:
            ents = sorted(os.listdir(r))
            print("n entries:", len(ents))
            for e in ents:
                if r.endswith("data_lake") or "ASD" in e or "asd" in e or "CovIn" in e:
                    p = os.path.join(r, e)
                    try:
                        sz = os.path.getsize(p)
                        isd = os.path.isdir(p)
                        print(f" - {e}  (dir={isd}, size={sz})")
                    except Exception:
                        print(f" - {e}")
        except Exception as ex:
            print("ERROR:", type(ex).__name__, ex)
